{"sql": "WITH q2 AS (
  SELECT order_id FROM orders
  WHERE order_purchase_timestamp >= '2018-04-01' AND order_purchase_timestamp < '2018-07-01'
)
SELECT count(*) AS multi_review_orders
FROM (
  SELECT q.order_id FROM q2 q JOIN order_reviews r ON r.order_id = q.order_id
  GROUP BY q.order_id HAVING count(*) > 1
) t"}
